INSERT INTO restoration_cases VALUES (1, 'CASE-FEEDER-REPEAT',      'Feeder fault repeat outage prevention',    'critical', 'open',       1, 97.2, 'Service Point 1001 connects to outage event OUT-1042, Feeder NV-12, missed restoration ETA outreach, demand response reconciliation, and 7-day repeat outage risk.', SYSTIMESTAMP);
INSERT INTO restoration_cases VALUES (2, 'CASE-XFMR-LOAD-GAP',      'Transformer overload reliability closure',  'high',     'open',       2, 84.5, 'Service Points 1002 and 1007 share transformer overload, AMI voltage monitoring gap, DER backfeed constraint, and field supervisor ownership.', SYSTIMESTAMP);
INSERT INTO restoration_cases VALUES (3, 'CASE-STORM-CREW-ACCESS',  'Storm crew access mitigation',             'high',     'open',       5, 90.1, 'Service Point 1005 connects pole damage, vegetation contact, Westgate depot coordination, and crew access constraints.', SYSTIMESTAMP);
