INSERT INTO restoration_cases VALUES (6, 'CASE-WATER-WASTEWATER',   'Water pressure and wastewater compliance',  'high',     'monitoring', 220, 94.0, 'Water main break WMB-4417 and wastewater compliance event WWC-9031 connect pressure zones, treatment assets, compliance record CMP-4420, and repair milestones.', SYSTIMESTAMP);
INSERT INTO restoration_cases VALUES (7, 'CASE-UPSTREAM-PRODUCTION','Well production optimization and HSE',      'high',     'open',       240, 91.0, 'Well WELL-NB-014 connects production variance, artificial lift review, Delta Production Facility FAC-DELTA-03, produced-water handling, emissions, and maintenance plan MP-6082.', SYSTIMESTAMP);
