/*
 * load_service_restoration_graph.sql
 * Synthetic Energy & Utilities property graph data.
 *
 * The graph answers utilities-native questions about electric outages,
 * gas leak response, water/wastewater operations, oil & gas production,
 * pipeline integrity, refinery constraints, LNG logistics, emissions,
 * HSE incidents, field crew dispatch, customer notification, and compliance.
 */

SET SERVEROUTPUT ON
SET SQLBLANKLINES ON
SET DEFINE OFF

PROMPT Loading operational event graph data...

BEGIN
  DELETE FROM restoration_case_entities;
  DELETE FROM restoration_cases;
  DELETE FROM utility_graph_relationships;
  DELETE FROM utility_graph_entities;
  COMMIT;
END;
/

-- Vertices: electric utility, gas utility, water/wastewater, upstream, midstream,
-- downstream, HSE, emissions, customer, crew, work order, compliance, and milestone records.









-- Cross-sector operational events and assets.



UPDATE utility_graph_entities
SET operations_label =
      CASE entity_type
        WHEN 'service_point' THEN 'Service Point: ' || display_name
        WHEN 'outage_event' THEN 'Outage Event: ' || display_name
        WHEN 'root_cause' THEN 'Root Cause: ' || display_name
        WHEN 'demand_response_event' THEN 'Demand Response: ' || display_name
        WHEN 'repair_action' THEN 'Repair Action: ' || display_name
        WHEN 'field_crew' THEN 'Field Crew: ' || display_name
        WHEN 'substation' THEN 'Substation or Depot: ' || display_name
        WHEN 'reliability_gap' THEN 'Reliability Gap: ' || display_name
        WHEN 'asset' THEN 'Grid Asset: ' || display_name
        WHEN 'meter_event' THEN 'Meter Event: ' || display_name
        WHEN 'gas_leak_event' THEN 'Gas Leak Event: ' || display_name
        WHEN 'water_main_break' THEN 'Water Main Break: ' || display_name
        WHEN 'wastewater_overflow_event' THEN 'Wastewater Compliance Event: ' || display_name
        WHEN 'pipeline_anomaly' THEN 'Pipeline Anomaly: ' || display_name
        WHEN 'well_production_issue' THEN 'Well Production Issue: ' || display_name
        WHEN 'refinery_constraint' THEN 'Refinery Constraint: ' || display_name
        WHEN 'lng_logistics_delay' THEN 'LNG Logistics Delay: ' || display_name
        WHEN 'emissions_event' THEN 'Emissions Event: ' || display_name
        WHEN 'hse_incident' THEN 'HSE Incident: ' || display_name
        WHEN 'affected_customer' THEN 'Affected Customer: ' || display_name
        WHEN 'affected_asset' THEN 'Affected Asset: ' || display_name
        WHEN 'inspection' THEN 'Inspection: ' || display_name
        WHEN 'work_order' THEN 'Work Order: ' || display_name
        WHEN 'compliance_record' THEN 'Compliance Record: ' || display_name
        WHEN 'resolution_milestone' THEN 'Resolution Milestone: ' || display_name
        WHEN 'pipeline_segment' THEN 'Pipeline Segment: ' || display_name
        WHEN 'well' THEN 'Well: ' || display_name
        WHEN 'production_facility' THEN 'Production Facility: ' || display_name
        WHEN 'compressor_station' THEN 'Compressor Station: ' || display_name
        WHEN 'refinery_unit' THEN 'Refinery Unit: ' || display_name
        WHEN 'lng_terminal' THEN 'LNG Terminal: ' || display_name
        WHEN 'storage_facility' THEN 'Storage Facility: ' || display_name
        WHEN 'water_treatment_plant' THEN 'Water Treatment Plant: ' || display_name
        WHEN 'wastewater_facility' THEN 'Wastewater Facility: ' || display_name
        WHEN 'pump_station' THEN 'Pump Station: ' || display_name
        WHEN 'sensor_reading' THEN 'Sensor Reading: ' || display_name
        WHEN 'maintenance_plan' THEN 'Maintenance Plan: ' || display_name
        ELSE display_name
      END,
    description = summary
WHERE operations_label IS NULL
   OR description IS NULL;

-- Edges: operational-event traversal paths.









-- Gas utility and oil & gas midstream integrity relationships.

-- Water and wastewater operations relationships.

-- Oil & Gas upstream, midstream, downstream, HSE, and emissions relationships.

COMMIT;

-- Case vertices and case-to-entity evidence edges.










COMMIT;

DECLARE
  v_entities NUMBER;
  v_edges    NUMBER;
  v_cases    NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_entities FROM utility_graph_entities;
  SELECT COUNT(*) INTO v_edges    FROM utility_graph_relationships;
  SELECT COUNT(*) INTO v_cases    FROM restoration_cases;
  DBMS_OUTPUT.PUT_LINE('Operational event graph loaded: ' || v_entities || ' entities, ' || v_edges || ' relationships, ' || v_cases || ' cases.');
END;
/
